import{_ as t,a,o as r,a4 as o}from"./chunks/framework.-FZumj2l.js";const g=JSON.parse('{"title":"Categories","description":"","frontmatter":{"outline":false,"apiType":"rest"},"headers":[],"relativePath":"api/rest-api/shop/categories/index.md","filePath":"api/rest-api/shop/categories/index.md","lastUpdated":1783079210000}'),i={name:"api/rest-api/shop/categories/index.md"};function s(n,e,h,d,l,c){return r(),a("div",null,e[0]||(e[0]=[o('<h1 id="categories" tabindex="-1">Categories <a class="header-anchor" href="#categories" aria-label="Permalink to &quot;Categories&quot;">​</a></h1><p>The Categories menu exposes the store&#39;s catalog category structure — the browsable departments and sub-departments a shopper navigates. You can read categories as a flat list (with optional filtering) or as a nested tree that mirrors the storefront&#39;s category navigation.</p><h2 id="flat-list-vs-tree" tabindex="-1">Flat list vs. tree <a class="header-anchor" href="#flat-list-vs-tree" aria-label="Permalink to &quot;Flat list vs. tree&quot;">​</a></h2><ul><li>The <strong>flat list</strong> returns categories as individual rows. Use it when you want to fetch, filter or page through categories without their hierarchy.</li><li>The <strong>tree</strong> returns categories nested under their parents in one response. Use it to render a navigation menu or a category sidebar without stitching the hierarchy together yourself.</li></ul><p>Only storefront-visible (enabled) categories are returned. Pass a <code>locale</code> to receive category names and content in that language.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Method &amp; Path</th><th>Description</th></tr></thead><tbody><tr><td><a href="/api/rest-api/shop/categories/get-categories.html">Categories</a></td><td><code>GET /api/shop/categories</code></td><td>Flat list of storefront categories.</td></tr><tr><td><a href="/api/rest-api/shop/categories/get-category-tree.html">Category Tree</a></td><td><code>GET /api/shop/category-trees</code></td><td>Nested category tree for navigation.</td></tr></tbody></table><p>All Category endpoints are public reads that require only the storefront key — see <a href="/api/rest-api/authentication.html">Authentication</a>.</p>',8)]))}const u=t(i,[["render",s]]);export{g as __pageData,u as default};
